package sidecar

import (
	"fmt"
	"strconv"
	"strings"
	"time"

	"github.com/brian-nunez/breadboard/internal/catalog"
)

// pgbouncerAuthFile is written at container start from the environment,
// so the password never lands in a generated file.
const pgbouncerAuthFile = "/tmp/pgbouncer/userlist.txt"

func renderPgBouncer(in Input) (Output, error) {
	pb := in.Spec.PgBouncer
	if pb == nil {
		return Output{}, fmt.Errorf("sidecar %s: no pgbouncer settings", in.Name)
	}
	use, ok := in.use(pb.Service)
	if !ok {
		return Output{}, fmt.Errorf("sidecar %s: %s is not in the app's uses", in.Name, pb.Service)
	}
	db, user := use.Config["database"], use.Config["user"]
	pw := in.Secret(pb.Service)("password")
	ini := strings.Join([]string{
		"; Generated by Breadboard for " + in.Name + ": a connection pool on loopback in front of " + pb.Service + ".",
		"; The app connects in plaintext to 127.0.0.1 (inside its pod); PgBouncer connects",
		"; to Postgres over TLS, verifying its certificate and name against the lab CA.",
		"[databases]",
		fmt.Sprintf("%s = host=%s port=%d dbname=%s", db, use.FQDN, use.Port, db),
		"",
		"[pgbouncer]",
		"listen_addr = 127.0.0.1",
		"listen_port = " + strconv.Itoa(pb.Port),
		"unix_socket_dir =",
		"; The app logs in with its own Postgres credentials; PgBouncer reuses them",
		"; for its server connections.",
		"auth_type = scram-sha-256",
		"auth_file = " + pgbouncerAuthFile,
		"pool_mode = " + pb.PoolMode,
		"default_pool_size = " + strconv.Itoa(pb.PoolSize),
		"max_client_conn = 200",
		"server_tls_sslmode = verify-full",
		"server_tls_ca_file = " + catalog.CAFile,
		"ignore_startup_parameters = extra_float_digits",
		"admin_users = " + user,
		"stats_users = " + user,
		"log_connections = 1",
		"log_disconnections = 1",
	}, "\n") + "\n"
	start := strings.Join([]string{
		"set -eu",
		"umask 077",
		"mkdir -p " + pathDir(pgbouncerAuthFile),
		`printf '"%s" "%s"\n' "$$BB_PG_USER" "$$BB_PG_PASSWORD" > ` + pgbouncerAuthFile,
		"exec pgbouncer " + catalog.ConfigDir + "/pgbouncer.ini",
	}, "\n")
	port := strconv.Itoa(pb.Port)
	out := Output{
		Container: catalog.Container{
			Entrypoint: []string{"/bin/sh", "-c", start},
			Environment: []catalog.EnvVar{
				{Name: "BB_PG_USER", Value: user},
				{Name: "BB_PG_PASSWORD", Value: pw, Secret: true},
			},
			Files: []catalog.File{{Name: "pgbouncer.ini", Data: []byte(ini)}},
			Health: catalog.Health{
				Test:          []string{"CMD", "pg_isready", "-q", "-h", "127.0.0.1", "-p", port},
				Interval:      10 * time.Second,
				Timeout:       3 * time.Second,
				Retries:       3,
				StartPeriod:   20 * time.Second,
				StartInterval: 1 * time.Second,
			},
		},
		Needs:    []string{pb.Service},
		Rewrites: pb.Service,
	}
	// The app's variables for the service point at the pool instead.
	rewrite := map[string]catalog.EnvVar{
		"DATABASE_URL": {Value: fmt.Sprintf("postgres://%s:%s@127.0.0.1:%d/%s?sslmode=disable", user, pw, pb.Port, db), Secret: true},
		"PGHOST":       {Value: "127.0.0.1"},
		"PGPORT":       {Value: port},
		"PGSSLMODE":    {Value: "disable"},
	}
	for _, v := range use.Env {
		for base, nv := range rewrite {
			if v.Name == base || v.Name == envPrefixed(pb.Service, base) {
				nv.Name = v.Name
				out.AppEnv = append(out.AppEnv, nv)
			}
		}
	}
	return out, nil
}

// envPrefixed is the name a variable gets when a second service of the
// same type is used (secrets.EnvPrefixed, which this package cannot import).
func envPrefixed(service, name string) string {
	return strings.ToUpper(strings.NewReplacer("-", "_", ".", "_").Replace(service)) + "_" + name
}

func pathDir(p string) string { return p[:strings.LastIndex(p, "/")] }

// use finds one of the app's used services.
func (in Input) use(service string) (Use, bool) {
	for _, u := range in.Uses {
		if u.Service == service {
			return u, true
		}
	}
	return Use{}, false
}
